import React from 'react';

import PageLoader from '@components/PageLoader';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import PohBreadcrumbs from '@ui-kit/Breadcrumb';
import PohContainer from '@ui-kit/layout/Container';

import { getInterviewById } from '../@services/interview.service';
import { IInterview } from '../@types/interview.types';
import InterviewResult from '../components/InterviewResult';

interface IInterviewMyResultPageProps {
  id_interview: number;
}

const InterviewMyResultPage: React.FC<IInterviewMyResultPageProps> = ({ id_interview }) => {
  const [isLoading, setIsLoading] = React.useState(true);
  const [err, setErr] = React.useState<Error>();
  const [data, setData] = React.useState<IInterview>();
  const load = React.useCallback(async () => {
    try {
      setIsLoading(true);
      const res = await getInterviewById(id_interview);
      setData(res);
    } catch (e) {
      setErr(e as Error);
    } finally {
      setIsLoading(false);
    }
  }, [id_interview]);

  React.useEffect(() => {
    load();
  }, [load]);

  if (isLoading) return <PageLoader />;
  if (err) return <PohAlert variant={AlertVariant.Danger}>{err.message}</PohAlert>;
  if (!data)
    return <PohAlert variant={AlertVariant.Danger}>Has no interview {id_interview}</PohAlert>;

  return (
    <div>
      <PohBreadcrumbs
        data={[
          { href: '/iv', text: 'Опросы' },
          { href: '/iv/' + id_interview, text: data.name },
          { href: '/iv/' + id_interview, text: 'Мой ответ', active: true },
        ]}
      />

      <PohContainer>
        <h3 className="mb-0">Мой ответ на опрос {data.name}</h3>
        <p className="mt-0 text-muted">{data.description}</p>
        <InterviewResult id_interview={id_interview} />
      </PohContainer>
    </div>
  );
};

export default InterviewMyResultPage;
